def gen(v, lang):
    names = GEN_NAMES[v]
    art = "des" if lang == "de" else "vom"
    parts = [f"[{art} {n}]{{{2 * i + 1},{2 * i + 2}}}" for i, n in enumerate(names)]
    if v == 38:
        parts.append("[Gottes]{7,8}" if lang == "de" else "[vo Gott]{7,8}")
        return ", ".join(parts) + "."
    return ", ".join(parts) + ","


